#include <vector>
#include <omp.h>

void reversePrefixSum(std::vector<int> const& x, std::vector<int> &output) {
    const std::size_t n = x.size();
    output.resize(n);
    if (n == 0) return;

    int max_threads = 1;
#pragma omp parallel
    {
#pragma omp single
        {
            max_threads = omp_get_num_threads();
        }
    }

    std::vector<long long> block_sums(max_threads, 0);

#pragma omp parallel
    {
        const int tid = omp_get_thread_num();
        const int nt = omp_get_num_threads();

        const std::size_t chunk = (n + static_cast<std::size_t>(nt) - 1) / static_cast<std::size_t>(nt);
        const std::size_t start = static_cast<std::size_t>(tid) * chunk;
        std::size_t end = start + chunk;
        if (end > n) end = n;

        if (start < n) {
            long long running = 0;
            for (std::size_t i = start; i < end; ++i) {
                running += x[i];
                output[i] = static_cast<int>(running);
            }
            block_sums[tid] = running;
        } else {
            block_sums[tid] = 0;
        }

#pragma omp barrier

#pragma omp single
        {
            long long carry = 0;
            for (int t = 0; t < nt; ++t) {
                const long long tmp = block_sums[t];
                block_sums[t] = carry;
                carry += tmp;
            }
        }

        if (start < n) {
            const long long offset = block_sums[tid];
            for (std::size_t i = start; i < end; ++i) {
                output[i] = static_cast<int>(static_cast<long long>(output[i]) + offset);
            }
        }
    }
}
